#!/usr/bin/env python3
"""data/newzealand.js (window.REGION_ICE) for the region 'nz' (New Zealand): Franz Josef Glacier, from the onboarding session experiments/onboard/franz-josef/ (local, gitignored).

What is in it: the outlines of the GLIMS Glacier Database (NSIDC-0272 v1) for 1978 (Chinn, via RGI) and 2019 (Carrivick et al., Google Earth Engine) as the two outlines of the page, the areas of
all six dated outlines as the database states them (rounded to 2 decimals), the tongue tip, the picture box, the strip, and the highest and lowest point of the 2019 outline COMPUTED from the LINZ
1 m DEM (the page says so). Nothing else is copied from outside: the texts are in js/07b-icecap-texts.js with their sources.
Also writes the local records data/regions/nz/franz-josef/ (glacier.json, outlines.json, scenes.json) so that `npm run walkthrough -- export` makes data/boxes.js, data/scenes.json and
worker/glacier-index.json; the records are marked as imported from the onboarding session (the steps the owner set there, with their times), not as confirmed in the walkthrough.
Usage (repo root, the project venv with shapely, pyproj, numpy): experiments/aletsch-yearly-dem/.venv/bin/python scripts/build_newzealand.py
"""
import json, os, math, datetime
import numpy as np
from shapely.geometry import shape
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
S = os.path.join(ROOT, 'experiments', 'onboard', 'franz-josef')
sess = json.load(open(os.path.join(S, 'session.json')))
feat = {f['properties']['key']: f for f in json.load(open(os.path.join(S, 'outlines.geojson')))['features']}
ring = lambda r: [[round(y, 5), round(x, 5)] for x, y in r]
def lines(f):
    g = f['geometry']; polys = g['coordinates'] if g['type'] == 'MultiPolygon' else [g['coordinates']]
    return [ring(r) for p in polys for r in p]
new, old = feat['glims-2019'], feat['glims-1978']
# highest and lowest point of the 2019 outline from the LINZ DEM (4 m mosaic of the strip area, elevation/linz-lidar-strip-4m.npz)
from pyproj import Transformer
from rasterio.features import rasterize; from rasterio.transform import from_origin
w = np.load(os.path.join(S, 'elevation', 'linz-lidar-strip-4m.npz')); WC = w['wc']; x0, y1, res = float(w['x0']), float(w['y1']), float(w['res'])
t = Transformer.from_crs(4326, 2193, always_xy=True).transform
from shapely.ops import transform as T
g = T(t, shape(new['geometry'])); m = rasterize([(g, 1)], out_shape=WC.shape, transform=from_origin(x0, y1, res, res), dtype='uint8').astype(bool) & np.isfinite(WC)
zmin, zmax = int(round(float(np.percentile(WC[m], 0.1)))), int(round(float(np.percentile(WC[m], 99.9))))   # 0.1 / 99.9 percentile: single noisy cells (cliffs, lidar spikes) do not set the extremes
ctr = shape(new['geometry']).representative_point(); c = shape(new['geometry']).centroid
st = sess['steps']['strip']['params']; tip = st['tip']; box = sess['steps']['box']['params']
bx = box.get('box') or box.get('bounds') or st['box']      # the picture box of the box step, [[south, west], [north, east]]
areas = [{'year': y, 'label': l, 'km2': round(feat[k]['properties']['area_km2'], 2)} for k, y, l in (('glims-1600', 1600, '1600, Little Ice Age moraines'), ('glims-1978', 1978, '1978'), ('glims-2000', 2000, '2000'), ('glims-2009', 2009, '2009'), ('glims-2016', 2016, '2016'), ('glims-2019', 2019, '2019'))]
outlet = {
    'id': 'franz-josef', 'name': 'Franz Josef Glacier', 'rgi': 'RGI60-18.02397', 'note': 'Kā Roimata o Hine Hukatere', 'tongueName': '',
    'areaKm2': round(new['properties']['area_km2'], 2), 'lengthKm': 0, 'zmin': zmin, 'zmax': zmax, 'hNote': 'calculated here from the lidar elevation model, inside the outline of 2019', 'hSrc': 'nz_linz', 'outlineYear': 2019,
    'lat': round((bx[0][0] + bx[1][0]) / 2, 5), 'lon': round((bx[0][1] + bx[1][1]) / 2, 5), 'half': round((bx[1][1] - bx[0][1]) / 2 * 111.32 * math.cos(math.radians((bx[0][0] + bx[1][0]) / 2)), 7), 'halfH': round((bx[1][0] - bx[0][0]) / 2 * 111.32, 7), 'box': bx, 'tip': tip, 'strip3d': {'azimuth': st['azimuth'], 'half': st['half'], 'back': st['back'], 'up': st['up'], 'cell': 16},
    'outline': [ring_ for ring_ in lines(new)], 'units': 1, 'areas': areas,
    'outlines': {'lia': {'year': 1978, 'label': '1978, Chinn (via RGI)', 'date': '1978-01-01', 'lines': lines(old)}, 'latest': {'year': 2019, 'label': '2019, Carrivick et al.', 'date': '2019-03-28', 'lines': lines(new)}},
}
data = {'source': 'GLIMS Glacier Database (NSIDC-0272 v1): outlines of 1978 (Chinn, via RGI) and 2019 (Carrivick et al., Google Earth Engine); heights computed from the LINZ lidar DEM',
        'icecap': {'name': 'New Zealand', 'areaKm2': 0, 'entities': 1}, 'outlets': [outlet], 'basins': []}
open(os.path.join(ROOT, 'data', 'newzealand.js'), 'w', encoding='utf-8').write('// generated by scripts/build_newzealand.py - do not edit by hand\n// Franz Josef Glacier, New Zealand\nwindow.REGION_ICE = ' + json.dumps(data, ensure_ascii=False, separators=(',', ':')) + ';\n')
print('data/newzealand.js', os.path.getsize(os.path.join(ROOT, 'data', 'newzealand.js')) // 1024, 'KB; zmin', zmin, 'zmax', zmax, 'areas', [a['km2'] for a in areas], 'rings', len(outlet['outline']))

# ---- the local records: made by the walkthrough's importer from the site files (js/regions.js entry `nz`, data/boxes.js, data/scenes.json, data/landsat/franz-josef.json), like every other region.
# Order: this script (data/newzealand.js) -> `npx tsx walkthrough/cli.ts import-site nz` (records data/regions/nz/, marked imported, nothing confirmed) -> `npm run walkthrough -- export` (data/boxes.js,
# data/scenes.json, worker/glacier-index.json). data/boxes.js must already hold franz-josef for the importer: on the first run write the record by hand (see docs/REFERENCE.md, row New Zealand) or run export once.
